def sw(on=True): return f'<button class="sw2 {"on" if on else ""}" role="switch" aria-checked="{"true" if on else "false"}"><i></i></button>'
def field(lbl, val, req=False, mono=False, help=''):
    return f'<label class="fld"><span class="lbl">{lbl}{" <b>*</b>" if req else ""}</span><span class="inp{" mono" if mono else ""}">{val}</span>{f"<small>{help}</small>" if help else ""}</label>'

