html=f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mockup · Conta</title><style>{fonts}{CSS}{EXTRA}{MOTION_CSS}</style></head><body>
<header class="doc"><p class="eyebrow">Zelo Design System · Fase 4 · mockup 05 de 06</p><h1>Perfil, Assinatura e Ferramentas</h1><p>Telas <code>/perfil</code> (hotspot), <code>/assinatura</code> (hotspot, cobrança) e <code>/ferramentas</code>. Tudo o que existe hoje continua: as 5 abas do perfil (Perfil, Empresa, Assinatura com histórico de faturas e portal de pagamentos, Preferências com impressão, plataformas, tabelas de preço e notificações, Integrações com operação offline e Zelo Impressão nos três estados), zona de perigo recolhida e a versão enxuta do subusuário. Na assinatura: avisos de origem (Mesas, Acessos, upgrade), status ativo ou teste, as 3 etapas (pacote, extensões com "já incluso" e aviso de perda de módulo, revisão com vencimento, CPF/CNPJ só quando falta, Pix ou cartão), resumo com total, barra fixa no celular, cancelar e o Pix com QR, contagem, copia e cola e "Já paguei". Nenhuma regra de cobrança muda; só apresentação.</p>
<ol><li><b>Perfil</b>: abas com indicador líquido, cartões por assunto, "Salvar alterações" vira loader → check.</li><li><b>Assinatura</b>: etapas como abas, cartões de pacote com seleção em navy, resumo lateral com o total que conta ao mudar.</li><li><b>Pix</b>: sheet com QR, contagem regressiva em Mono e cópia com check.</li><li><b>Ferramentas</b>: cartões com aperto no toque; Precificação e Cardápio seguem os padrões aprovados.</li></ol>
<p class="hint-motion">Com movimento: troque as abas do perfil, clique nas etapas e nos pacotes/extensões (o total conta), nos interruptores, em "Salvar" e em "Copiar código Pix".</p></header>
<section class="row"><h2 class="cap-h">1 · Perfil — desktop 1440 (troque as abas)</h2>{PERFIL_D}</section>
<section class="row"><h2 class="cap-h">2 · Assinatura — desktop 1440 (clique nas etapas e nos pacotes)</h2>{ASSIN_D}</section>
<section class="row"><h2 class="cap-h">3 · Pix — sheet</h2>{PIX}</section>
<section class="row"><h2 class="cap-h">4 · Ferramentas — desktop 1440</h2>{FERR_D}</section>
<section class="row mob"><div><h2 class="cap-h">5 · Perfil — celular 390</h2>{MOB_P}</div><div><h2 class="cap-h">6 · Assinatura — celular 390</h2>{MOB_A}</div></section>
<section class="row mob"><div><h2 class="cap-h">7 · Perfil · Empresa</h2>{M_EMP}</div><div><h2 class="cap-h">8 · Perfil · Assinatura</h2>{M_ASS}</div><div><h2 class="cap-h">9 · Perfil · Preferências</h2>{M_PREF}</div></section>
<section class="row mob"><div><h2 class="cap-h">10 · Integrações + zona de perigo</h2>{M_INT}</div><div><h2 class="cap-h">11 · Subusuário · Minha conta</h2>{M_SUB}</div><div><h2 class="cap-h">12 · Ferramentas</h2>{M_FERR}</div></section>
<section class="row mob"><div><h2 class="cap-h">13 · Assinatura · Extensões</h2>{M_STEP2}</div><div><h2 class="cap-h">14 · Assinatura · Pagamento</h2>{M_STEP3}</div><div><h2 class="cap-h">15 · Pix em sheet</h2>{M_PIX}</div></section>
{MOTION_JS}<script>
document.querySelectorAll('.cnt').forEach((el) => {{ const to = parseFloat(el.dataset.to); zCount(el, 0, to); }});
document.querySelectorAll('.sw2').forEach((b) => b.addEventListener('click', () => {{ b.classList.toggle('on'); b.setAttribute('aria-checked', b.classList.contains('on')); }}));
// perfil tabs → blur swap
document.querySelectorAll('.ptabs button[data-go]').forEach((b) => b.addEventListener('click', () => {{ const panes = b.closest('main').querySelector('.panes'); zSwap(panes, () => panes.querySelectorAll('.pane').forEach((p) => p.hidden = p.dataset.t !== b.dataset.go)); }}));
// assinatura wizard
const wiz = document.querySelector('#assin'); let step = 1;
const tabs = wiz.querySelectorAll('.steps button');
const go = (n) => {{ step = Math.max(1, Math.min(3, n)); tabs[step - 1].click(); }};
tabs.forEach((b) => b.addEventListener('click', () => {{ step = +b.dataset.step; const v = wiz.querySelector('.steps-v'); zSwap(v, () => v.querySelectorAll('.step').forEach((s) => s.hidden = +s.dataset.s !== step)); wiz.querySelector('[data-next]').textContent = step === 1 ? 'Continuar' : step === 2 ? 'Revisar e pagar' : 'Escolha Pix ou cartão'; }}));
wiz.querySelector('[data-next]').addEventListener('click', () => go(step + 1)); wiz.querySelector('[data-back]').addEventListener('click', () => go(step - 1));
const tot = wiz.querySelector('#tot'); let cur = 228;
const recalc = () => {{ const base = +wiz.querySelector('.plan.sel').dataset.price; const add = [...wiz.querySelectorAll('.addon.sel')].reduce((a, x) => a + +x.dataset.price, 0); const nv = base + add; zCount(tot, cur, nv); cur = nv; }};
wiz.querySelectorAll('.plan').forEach((p) => p.addEventListener('click', () => {{ wiz.querySelectorAll('.plan').forEach((x) => {{ x.classList.remove('sel'); x.querySelector('.pl-cta').textContent = 'Escolher pacote'; }}); p.classList.add('sel'); p.querySelector('.pl-cta').textContent = 'Novo pacote selecionado'; recalc(); }}));
wiz.querySelectorAll('.addon:not(.inc)').forEach((a) => a.addEventListener('click', () => {{ a.classList.toggle('sel'); const on = a.classList.contains('sel'); const pill = a.querySelector('.pill'); pill.textContent = on ? 'Selecionado' : 'Opcional'; pill.classList.toggle('on', on); recalc(); }}));
// button → loader → check
document.querySelectorAll('.morph-lite').forEach((b) => b.addEventListener('click', (e) => {{ e.preventDefault(); if (b.dataset.busy) return; const html = b.innerHTML; b.dataset.busy = 1; b.style.minWidth = b.offsetWidth + 'px'; b.innerHTML = '<svg class="ic spin-i" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><circle cx="12" cy="12" r="9" opacity=".2"/><path d="M12 3a9 9 0 0 1 9 9"/></svg>'; setTimeout(() => {{ b.innerHTML = '<svg class="ic popin" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>'; }}, 800); setTimeout(() => {{ b.innerHTML = html; delete b.dataset.busy; }}, 1900); }}));
// Pix countdown
const cd = document.querySelector('#cd'); let secs = 14 * 60 + 32; setInterval(() => {{ secs = Math.max(0, secs - 1); cd.textContent = String(Math.floor(secs / 60)).padStart(2, '0') + ':' + String(secs % 60).padStart(2, '0'); }}, 1000);
</script></body></html>'''
open('/home/user/zelopdv/docs/design-system/mockups/05-conta.html','w').write(html)
print('ok', len(html))
